package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Today mascot for a day whose work is finished: the cat sitting, content.
 *
 * A sitting pose like the empty Today cat, and the difference is the eyes:
 * curved shut where that cat's are half open and level. It marks the end of a
 * day that had work in it, which is why Today draws it only when something was
 * actually completed. See D-033, and D-074 for the pose it is read against.
 *
 * Drawn from `cat-hd-all-done`. It takes the same scale factor as the other
 * six. [MascotImage] explains why the paths are built in Kotlin and which
 * colour role each tone takes.
 */
@Composable
internal fun AllDoneMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::catSittingHappy
    )
}

private const val MascotWidth = 193.18f
private const val MascotHeight = 198.38f

private fun catSittingHappy(light: Color, mid: Color, dark: Color): ImageVector =
    ImageVector.Builder(
        name = "AllDoneCatSittingHappy",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = 743f,
        viewportHeight = 763f
    )
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Tail),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(PawShading1),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeLeft),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeRight),
            fill = SolidColor(dark)
        )
        .build()

